using Jira.Domain.Entities;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace Jira.Infrastructure.Persistence.Configurations;
public sealed class PlanningConfiguration : IEntityTypeConfiguration<IssueAssignee>, IEntityTypeConfiguration<IssueLabel>, IEntityTypeConfiguration<IssueRelease>, IEntityTypeConfiguration<ProjectComponent>, IEntityTypeConfiguration<ProjectRelease>, IEntityTypeConfiguration<Sprint>, IEntityTypeConfiguration<SprintIssue>
{
    private static void Columns<T>(EntityTypeBuilder<T> b) where T:class { foreach(var p in b.Metadata.GetProperties()) p.SetColumnName(System.Text.RegularExpressions.Regex.Replace(p.Name,"(?<!^)([A-Z])","_$1").ToLowerInvariant()); }
    public void Configure(EntityTypeBuilder<IssueAssignee> b) { b.ToTable("issue_assignees");b.HasKey(x=>new{x.IssueId,x.UserId});b.HasIndex(x=>new{x.TenantId,x.UserId});Columns(b); }
    public void Configure(EntityTypeBuilder<IssueLabel> b) { b.ToTable("issue_labels");b.HasKey(x=>x.Id);b.Property(x=>x.Label).HasMaxLength(100);b.HasIndex(x=>new{x.IssueId,x.Label}).IsUnique();Columns(b); }
    public void Configure(EntityTypeBuilder<IssueRelease> b) { b.ToTable("issue_releases");b.HasKey(x=>new{x.IssueId,x.ReleaseId,x.Kind});b.Property(x=>x.Kind).HasMaxLength(10);b.HasOne<ProjectRelease>().WithMany().HasForeignKey(x=>new{x.TenantId,x.ProjectId,x.ReleaseId}).HasPrincipalKey(x=>new{x.TenantId,x.ProjectId,x.Id}).OnDelete(DeleteBehavior.Restrict);Columns(b); }
    public void Configure(EntityTypeBuilder<ProjectComponent> b) { b.ToTable("components");b.HasKey(x=>x.Id);b.Property(x=>x.Name).HasMaxLength(150);b.HasIndex(x=>new{x.ProjectId,x.Name}).IsUnique();b.HasOne<Project>().WithMany().HasForeignKey(x=>new{x.TenantId,x.ProjectId}).HasPrincipalKey(x=>new{x.TenantId,x.Id}).OnDelete(DeleteBehavior.Cascade);Columns(b);b.Property(x=>x.Version).HasColumnName("xmin").IsRowVersion(); }
    public void Configure(EntityTypeBuilder<ProjectRelease> b) { b.ToTable("releases");b.HasKey(x=>x.Id);b.HasAlternateKey(x=>new{x.TenantId,x.ProjectId,x.Id});b.Property(x=>x.Name).HasMaxLength(200);b.Property(x=>x.ReleaseVersion).HasMaxLength(100);b.HasIndex(x=>new{x.ProjectId,x.ReleaseVersion}).IsUnique();b.HasOne<Project>().WithMany().HasForeignKey(x=>new{x.TenantId,x.ProjectId}).HasPrincipalKey(x=>new{x.TenantId,x.Id}).OnDelete(DeleteBehavior.Cascade);Columns(b);b.Property(x=>x.ReleaseVersion).HasColumnName("version");b.Property(x=>x.Version).HasColumnName("xmin").IsRowVersion(); }
    public void Configure(EntityTypeBuilder<Sprint> b) { b.ToTable("sprints");b.HasKey(x=>x.Id);b.Property(x=>x.Name).HasMaxLength(200);b.HasOne<Project>().WithMany().HasForeignKey(x=>new{x.TenantId,x.ProjectId}).HasPrincipalKey(x=>new{x.TenantId,x.Id}).OnDelete(DeleteBehavior.Cascade);b.HasIndex(x=>new{x.ProjectId,x.Status});Columns(b);b.Property(x=>x.Version).HasColumnName("xmin").IsRowVersion(); }
    public void Configure(EntityTypeBuilder<SprintIssue> b) { b.ToTable("sprint_issues");b.HasKey(x=>new{x.SprintId,x.IssueId});b.HasOne<Sprint>().WithMany().HasForeignKey(x=>x.SprintId).OnDelete(DeleteBehavior.Cascade);b.HasOne<Issue>().WithMany().HasForeignKey(x=>x.IssueId).OnDelete(DeleteBehavior.Cascade);Columns(b); }
}
